sp_widget.client_script:
function($scope, $timeout) {
  $scope.isFadingUltimos12Meses = false;
  $scope.dadosUltimos12Meses = $scope.data; 

  function ativarFade() {
    $scope.isFadingUltimos12Meses = true;
    $timeout(function() {
      $scope.isFadingUltimos12Meses = false;
    }, 500);
  }

  // Fade inicial (opcional)
  ativarFade();

  $scope.atualizarDados = function(novosDados) {
    ativarFade();
    $timeout(function() {
      $scope.dadosUltimos12Meses = novosDados;
    }, 500);
  };
}

sp_widget.css:
div, h2 {
   font-family: 'Roboto Flex', sans-serif;
 }

 .report-widget {
   border-radius: 12px;
   box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
   background-color: #fff;
   margin-top: 24px;
   overflow: hidden;
   display: flex;
   flex-direction: column;
   font-family: 'Roboto Flex', sans-serif;
   /* Transição para o fade + movimento vertical */
   opacity: 1;
   visibility: visible;
   transform: translateY(0);
   transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out, visibility 0.5s ease-in-out;
 }

 .report-widget.panel.fade-out {
   opacity: 0;
   visibility: hidden;
   transform: translateY(20px);
 }

 /* --- Media Queries para Responsividade --- */

 /* Telas Pequenas (Mobile S, M, L - até 767px) */
 @media (max-width: 767px) {
   .report-widget {
     margin-top: 1rem;
   }
   .panel-title {
     font-size: 1.5rem;
   }
   .panel-body {
     padding: 8px;
   }
 }

 /* Tablets (768px até 1023px) */
 @media (min-width: 768px) and (max-width: 1023px) {
   .report-widget {
     margin-top: 1.5rem;
   }
   .panel-title {
     font-size: 1.1rem;
   }
 }

 /* Laptops e Telas Maiores (1024px em diante) */
 @media (min-width: 1024px) {
   .report-widget {
     margin-top: 24px; /* Valor original */
   }
   .panel-title {
     font-size: 1.5em; /* Valor original */
   }
 }

 /* Ajustes para dispositivos muito largos (1280px em diante) */
 @media (min-width: 1280px) {
   .panel-heading {
     padding: 14px 18px;
   }
   .panel-body {
     padding: 20px;
   }
 }

 /* Ajustes Surface Duo (540x720) */
 @media (width: 540px) and (height: 720px) {
   .report-widget {
     margin-top: 1.2rem;
   }
   .panel-title {
     font-size: 1rem;
   }
 }

 /* Ajustes Galaxy Z Fold 5 (max-width: 350px) */
 @media (max-width: 350px) {
   .panel-title {
     font-size: 0.9rem;
   }
   .panel-body {
     padding: 6px;
   }
 }

 .panel-heading {
   font-family: 'Roboto Flex', sans-serif;
   background-color: #e0e0e0; /* fundo cinza claro */
   padding: 12px 16px;
   border-bottom: 1px solid #ccc;
   border-top-left-radius: 12px;
   border-top-right-radius: 12px;
 }

 .panel-title {
   font-family: 'Roboto Flex', sans-serif;
   margin: 0;
   font-size: 1.2em;
   color: #333;
   text-align: center;
 }

 .panel-body {
   font-family: 'Roboto Flex', sans-serif;
   padding: 16px;
   flex: 1;
   width: 100%;
 }

 /* Transição da mensagem "Nenhum dado" */
 .mensagem {
   opacity: 0;
   visibility: hidden;
   transform: translateY(20px);
   transition: opacity 0.5s ease-in-out, visibility 0.5s ease-in-out, transform 0.5s ease-in-out;
   height: 0;
   overflow: hidden;
 }

 .mensagem.show {
   opacity: 1;
   visibility: visible;
   transform: translateY(0);
   height: auto;
 }

sp_widget.script:
(function() {
    /*function formatarNumero(valor) {
  var resultado = (valor);
  resultado = resultado.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return resultado;
}
R$ 28.283.039.135.399.994
*/

	 function formatarNumero(valor) {
  if (typeof valor !== 'number') {
    valor = parseFloat(valor);
  }

  return valor.toFixed(2) // fixa duas casas decimais
              .replace('.', ',') // troca ponto decimal por vírgula
              .replace(/\B(?=(\d{3})+(?!\d))/g, '.'); // separador de milhar
}


  var gr = new GlideRecord('x_sded9_portal_t_0_u_rreo');
  gr.orderByDesc('u_ano');
  gr.orderByDesc('u_mes');
  gr.setLimit(12);
  gr.query();

  var soma = 0;
  var anoMaisRecente = null;

  while (gr.next()) {
    var valor = parseFloat(gr.getValue('adjusted_rreo_fiscal_management_report_2')) || 0;
    soma += valor;

    if (!anoMaisRecente) {
      anoMaisRecente = gr.getValue('u_ano');
    }
  }

  if (soma >= 0) {
    var valorFormatado = formatarNumero(soma);

    data.temDado = true;
    data.valorSoma = soma;
    data.valorSomaFormatado = valorFormatado;
    data.ano = anoMaisRecente;
    data.dados = [{
      ano: anoMaisRecente,
      valorSoma: soma,
      valorSomaFormatado: valorFormatado,
      temDado: true
    }];
  } else {
    data.temDado = false;
    data.ano = null;
    data.dados = [];
  }
})();
